## 建议的实现方向

```js
async function loadAll(ids, { concurrency = 8, retries = 2 } = {}) {
  const unique = [...new Set(ids)];
  const results = new Map();

  async function fetchOne(id, attempt = 0) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 8000);
    try {
      const r = await fetch(`/api/item/${id}`, { signal: ctrl.signal });
      if (!r.ok) {
        // 4xx 不重试；5xx / 429 重试
        const retryable = r.status >= 500 || r.status === 429;
        if (!retryable || attempt >= retries) {
          throw Object.assign(new Error(`HTTP ${r.status}`), { status: r.status, id });
        }
        const retryAfter = Number(r.headers.get('Retry-After')) * 1000 || 0;
        throw Object.assign(new Error(`HTTP ${r.status}`), { retryable: true, retryAfter, id });
      }
      results.set(id, { ok: true, data: await r.json() });
    } catch (err) {
      if (attempt < retries && (err.retryable || err.name === 'AbortError' || err.name === 'TypeError')) {
        const backoff = err.retryAfter || Math.min(2000, 100 * 2 ** attempt) * (0.5 + Math.random());
        await new Promise(r => setTimeout(r, backoff));   // 指数退避 + 抖动
        return fetchOne(id, attempt + 1);
      }
      results.set(id, { ok: false, error: err });         // 失败软着陆，不炸整体
    } finally {
      clearTimeout(timer);
    }
  }

  // 信号量式有界并发
  const queue = [...unique];
  await Promise.all(
    Array.from({ length: Math.min(concurrency, queue.length) }, async () => {
      while (queue.length) await fetchOne(queue.shift());
    })
  );

